import java.util.HashMap;
import java.util.Map;

/**
 * Generates truncated DNA sequences of varying lengths for profiling.
 * Uses real FASTA sequences and creates substrings for controlled experimentation.
 */
public class DnaSequenceGenerator {

    // Real DNA sequences (from resources)
    private static final String HUMAN_HBB = 
        "";

    private static final String CHIMPANZEE_HBB = 
        "";

    private static final Map<String, String> SEQUENCES = new HashMap<>();
    static {
        SEQUENCES.put("human", HUMAN_HBB);
        SEQUENCES.put("chimpanzee", CHIMPANZEE_HBB);
    }

    /**
     * Generate a DNA sequence of specified length.
     * If length exceeds available sequence, repeats the sequence.
     */
    public static String generateSequence(String name, int length) {
        String base = SEQUENCES.getOrDefault(name, HUMAN_HBB);
        if (length <= 0) {
            throw new IllegalArgumentException("Length must be positive");
        }
        
        StringBuilder sb = new StringBuilder();
        while (sb.length() < length) {
            int remaining = length - sb.length();
            if (remaining >= base.length()) {
                sb.append(base);
            } else {
                sb.append(base.substring(0, remaining));
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        // Test generation
        String seq100 = generateSequence("human", 100);
        String seq500 = generateSequence("human", 500);
        String seq1000 = generateSequence("human", 1000);
        
        System.out.println("Generated sequences:");
        System.out.println("  100bp: " + seq100.length() + " chars");
        System.out.println("  500bp: " + seq500.length() + " chars");
        System.out.println("  1000bp: " + seq1000.length() + " chars");
        
        // Return sequences in URL-safe format
        System.out.println("\nSeq100: " + seq100);
        System.out.println("Seq500: " + seq500);
        System.out.println("Seq1000: " + seq1000);
    }
}
